package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="recordatorios_cita") public class RecordatorioCita { @Id @GeneratedValue private UUID id; @Column(name="empresa_id") private UUID empresaId; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="cita_id") private Cita cita; private String canal; @Column(name="fecha_programada") private LocalDateTime fechaProgramada; private String estado="PENDIENTE"; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Cita getCita(){return cita;} public void setCita(Cita v){cita=v;} public String getCanal(){return canal;} public void setCanal(String v){canal=v;} public LocalDateTime getFechaProgramada(){return fechaProgramada;} public void setFechaProgramada(LocalDateTime v){fechaProgramada=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
